List<Integer> buffer = new ArrayList<>();

// Consumer
synchronized(buffer) {
    while (buffer.isEmpty()) { // while, not if!
        buffer.wait(); // releases lock, waits
    }
    int item = buffer.remove(0);
}

// Producer
synchronized(buffer) {
    buffer.add(item);
    buffer.notify(); // wake up consumer
}
