synchronized(lock) {
    // WRONG: if-statement doesn't handle spurious wakeup
    if (queue.isEmpty()) {
        lock.wait();
    }
    process(queue.poll()); // might be null if spurious wakeup!

    // CORRECT: while-loop rechecks condition
    while (queue.isEmpty()) {
        lock.wait(); // may return without notify
    }
    process(queue.poll()); // always valid
}
