```java
BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(10);

// Producer
new Thread(() -> {
    queue.put(item); // blocks if queue is full
}).start();

// Consumer
new Thread(() -> {
    Integer item = queue.take(); // blocks if queue is empty
    process(item);
}).start();
// No manual synchronized, wait(), or notify() needed!
